def _links(t):
    """vals[k], left[k], right[k] for the k-th real node in level order (-1 = no child)."""
    pos, c = [], 0
    for x in t:
        if x == -1:
            pos.append(-1)
        else:
            pos.append(c)
            c += 1
    vals = [x for x in t if x != -1]
    left, right = [-1] * c, [-1] * c
    for k in range(c):
        a = 2 * k + 1
        if a < len(t):
            left[k] = pos[a]
        if a + 1 < len(t):
            right[k] = pos[a + 1]
    return vals, left, right


def countGoodNodes(tree):
    vals, left, right = _links(tree)
    n = len(vals)
    if n == 0:
        return 0
    top = [0] * n            # largest value on the path from the root to node k, inclusive
    top[0] = vals[0]
    good = 1
    for k in range(n):
        for c in (left[k], right[k]):
            if c != -1:
                if vals[c] >= top[k]:
                    good += 1
                top[c] = max(top[k], vals[c])
    return good
